import hashlib, json, re
from html.parser import HTMLParser

class ExactSectionBounds(HTMLParser):
    def __init__(self, text):
        super().__init__(convert_charrefs=True)
        self.text = text
        self.starts = [0]
        for i, character in enumerate(text):
            if character == '\n':
                self.starts.append(i + 1)
        self.sections = []
        self.matches = []
        self.target_count = 0
    def offset(self):
        line, column = self.getpos()
        return self.starts[line - 1] + column
    def handle_starttag(self, tag, attrs):
        fields = dict(attrs)
        if tag == 'section':
            section = {'id': fields.get('id'), 'start': self.offset(), 'start_line': self.getpos()[0], 'examples': 0}
            if section['id'] == 'A8':
                self.target_count += 1
            self.sections.append(section)
        classes = (fields.get('class') or '').split()
        if 'ltx_theorem_example' in classes:
            for section in self.sections:
                section['examples'] += 1
    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)
    def handle_endtag(self, tag):
        if tag == 'section' and self.sections:
            section = self.sections.pop()
            if section['id'] == 'A8':
                close_start = self.offset()
                close_end = self.text.find('>', close_start)
                if close_end < 0:
                    raise ValueError('missing closing tag')
                close_end += 1
                opening_valid = self.text[section['start']:section['start'] + 8].lower() == '<section'
                closing_valid = re.fullmatch(r'</\s*section\s*>', self.text[close_start:close_end], re.IGNORECASE) is not None
                if not opening_valid or not closing_valid:
                    raise ValueError('invalid tag boundary')
                start_byte = len(self.text[:section['start']].encode('utf-8'))
                end_byte = len(self.text[:close_end].encode('utf-8'))
                section_bytes = self.text[section['start']:close_end].encode('utf-8')
                self.matches.append({'section_id': 'A8', 'start_line': section['start_line'], 'closing_tag_line': self.getpos()[0], 'start_character': section['start'], 'end_character_exclusive': close_end, 'start_byte': start_byte, 'end_byte_exclusive': end_byte, 'section_bytes': len(section_bytes), 'section_sha256': hashlib.sha256(section_bytes).hexdigest(), 'example_elements': section['examples'], 'tag_boundaries_valid': True})

try:
    with open(SOURCE_PATH, 'rb') as f:
        raw = f.read()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != SOURCE_SHA256:
        print(json.dumps({'state': 'SOURCE_HASH_MISMATCH', 'source_sha256': digest}, sort_keys=True))
    else:
        text = raw.decode('utf-8', errors='strict')
        scanner = ExactSectionBounds(text)
        scanner.feed(text)
        scanner.close()
        candidates = scanner.matches
        if scanner.target_count != 1 or len(candidates) != 1:
            state = 'ABSENT_OR_AMBIGUOUS_STOP'
        elif candidates[0]['start_line'] != 2129 or candidates[0]['closing_tag_line'] != 2228:
            state = 'STRUCTURE_MISMATCH_STOP'
        elif candidates[0]['example_elements'] != 0:
            state = 'EXAMPLE_ELEMENTS_PRESENT_STOP'
        else:
            state = 'STRUCTURAL_RANGE_ONLY'
        print(json.dumps({'state': state, 'source_sha256': digest, 'matches': candidates}, sort_keys=True))
except Exception as e:
    print(json.dumps({'state': 'LOCATOR_ERROR_STOP', 'error_type': type(e).__name__}, sort_keys=True))
